<!-- =================================================================== -->
<!-- PHYSICS CORE (pure: no DOM, deterministic, extractable for node)    -->
<!-- [PHYSICS-CORE-START] ... [PHYSICS-CORE-END]                        -->
<!-- =================================================================== -->
<script id="physics-core">
/* @physics-core-start */
/* d20 = regular icosahedron. 12 vertices (golden-ratio construction),
   20 equilateral faces numbered 1..20, opposite faces sum to 21.
   6-DOF rigid body: pos(3), quat(4), linVel(3), angVel(3).
   Semi-implicit Euler, fixed sub-steps. Table = plane y=0.
   Contact = lowest vertex (or two near-tied vertices); impulse with
   restitution (normal) + Coulomb friction (tangential) + angular loss.
   Soft rectangular walls. Settle detector + face-up read.
   Deterministic: NO Math.random() in this path. */
(function (global) {
  'use strict';

  // ---- constants (SI-ish; feel tuned later, correctness first) ---------
  const G = 9.817;               // gravity (m/s^2)
  const R_CIRC = 0.03;           // die circumscribed radius (m), vertex->center
  const MASS = 0.01;             // die mass (10 g)
  const SUB_DT = 1 / 240;        // fixed physics sub-step (s)
  const RESTITUTION = 0.35;      // table normal restitution
  const FRICTION = 0.5;          // table Coulomb mu
  const WALL_E = 0.4;            // wall restitution
  const WALL_F = 0.6;            // wall friction
  const CONTACT_ANG_LOSS = 0.02; // angular energy bleed per sub-step on contact
  const REST_LIN = 0.03;         // m/s: |v| below this counts as "still"
  const REST_ANG = 1.0;          // rad/s: |w| below this counts as "still"
  const REST_WINDOW = 0.15;      // s of sustained stillness to declare rest
  const SETTLE_T_MAX = 25;       // s: hard cap to declare "settled" (defensive)
  const TABLE_HALF = 0.24;       // soft-wall half-extent (m) -> 0.48 x 0.48 table
  const TWO_V_TOL = R_CIRC * 0.06; // near-tied lowest-vertex tolerance (m)
  const V_REST = 0.25;           // m/s: below this approach speed, restitution e=0
  const PEN_CORRECT = 0.12;      // fraction of penetration removed per sub-step
  const PEN_EPS = 1e-6;          // m: ignore penetration smaller than this
  // Rest damper: bleeds the low-energy rock to a full stop. Real dice lose
  // energy at the contact point (friction, deformation); the rocking on a
  // face is damped by friction at the pivot. This is that contact energy loss,
  // applied only while the die is already slow and in contact with the table,
  // so it never touches the throw or the bounces.
  const SLOW_VEL = 0.4;          // m/s: speed below which the rest damper engages
  const SLOW_ANG = 3.5;          // rad/s: speed below which the rest damper engages
  const REST_DAMP = 0.35;        // per-substep exponential decay of speed at rest
  const THROW_SPEED_MAX = 9;     // m/s: max fling speed (throwFromFling clamps |v| here)

  // ---- deterministic PRNG (mulberry32); ONLY for generating test states --
  function prng(seed) {
    let a = seed >>> 0;
    return function () {
      a = (a + 0x6D2B79F5) >>> 0;
      let t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // ---- vector helpers (plain [x,y,z]) ----------------------------------
  const v3 = (x, y, z) => [x, y, z];
  const vAdd = (a, b) => [a[0]+b[0], a[1]+b[1], a[2]+b[2]];
  const vSub = (a, b) => [a[0]-b[0], a[1]-b[1], a[2]-b[2]];
  const vScale = (a, s) => [a[0]*s, a[1]*s, a[2]*s];
  const vDot = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
  const vCross = (a, b) => [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
  const vLen = a => Math.sqrt(vDot(a, a));
  const vNorm = a => { const l = vLen(a); return l > 1e-12 ? vScale(a, 1/l) : v3(0,0,0); };

  // ---- quaternion helpers (x,y,z,w) ------------------------------------
  const qIdentity = () => [0, 0, 0, 1];
  function qFromAxisAngle(axis, angle) {
    const s = Math.sin(angle / 2), c = Math.cos(angle / 2);
    const a = vNorm(axis);
    return [a[0]*s, a[1]*s, a[2]*s, c];
  }
  function qMul(a, b) {
    const ax=a[0], ay=a[1], az=a[2], aw=a[3];
    const bx=b[0], by=b[1], bz=b[2], bw=b[3];
    return [
      aw*bx + ax*bw + ay*bz - az*by,
      aw*by - ax*bz + ay*bw + az*bx,
      aw*bz + ax*by - ay*bx + az*bw,
      aw*bw - ax*bx - ay*by - az*bz
    ];
  }
  function qNorm(q) {
    const l = Math.sqrt(q[0]*q[0]+q[1]*q[1]+q[2]*q[2]+q[3]*q[3]);
    return l > 1e-12 ? [q[0]/l, q[1]/l, q[2]/l, q[3]/l] : qIdentity();
  }
  function qRotate(q, v) { // v' = q v q^-1 (q unit)
    const x=q[0], y=q[1], z=q[2], w=q[3];
    const tx = 2*(y*v[2] - z*v[1]);
    const ty = 2*(z*v[0] - x*v[2]);
    const tz = 2*(x*v[1] - y*v[0]);
    return [
      v[0] + w*tx + (y*tz - z*ty),
      v[1] + w*ty + (z*tx - x*tz),
      v[2] + w*tz + (x*ty - y*tx)
    ];
  }

  // ---- convex-polyhedron face extraction --------------------------------
  // Returns { faces: index-triples, edges, adj } for a convex polyhedron.
  function extractFaces(vertices) {
    const n = vertices.length;
    let edge = Infinity;
    for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
      const d = vLen(vSub(vertices[i], vertices[j]));
      if (d < edge) edge = d;
    }
    const adj = Array.from({length: n}, () => []);
    const EPS = edge * 1e-6;
    for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
      if (Math.abs(vLen(vSub(vertices[i], vertices[j])) - edge) < EPS) { adj[i].push(j); adj[j].push(i); }
    }
    // face test: (i,j,k) is a face iff i-j and j-k are edges and the three are
    // coplanar & form an outward triangle. For a convex polyhedron, each edge
    // bounds exactly two faces. We enumerate, per vertex, the 5 neighbors in
    // angular order about the radial direction; consecutive pairs are faces.
    const faceSet = new Set();
    const key = (a,b,c) => [a,b,c].sort((x,y)=>x-y).join(',');
    for (let i = 0; i < n; i++) {
      const ri = vNorm(vertices[i]);
      let ref = [1,0,0];
      if (Math.abs(vDot(ri, ref)) > 0.9) ref = [0,1,0];
      const u = vNorm(vSub(ref, vScale(ri, vDot(ri, ref)))); // ref minus radial comp
      const w = vNorm(vCross(ri, u));
      const order = adj[i].map(nn => {
        const d = vNorm(vSub(vertices[nn], vertices[i]));
        return [nn, Math.atan2(vDot(d, w), vDot(d, u))];
      }).sort((p, q) => p[1] - q[1]);
      for (let k = 0; k < order.length; k++) {
        const a = order[k][0], b = order[(k + 1) % order.length][0];
        faceSet.add(key(i, a, b));
      }
    }
    const faces = Array.from(faceSet).map(s => s.split(',').map(Number));
    // consistent winding: outward normal (a x b) dot (centroid) > 0
    for (let f = 0; f < faces.length; f++) {
      const [a, b, c] = faces[f];
      const A = vertices[a], B = vertices[b], C = vertices[c];
      const nm = vCross(vSub(B, A), vSub(C, A));
      const cent = vScale(vAdd(vAdd(A, B), C), 1/3);
      if (vDot(nm, cent) < 0) faces[f] = [c, b, a]; // flip to outward
    }
    return { faces, adj };
  }

  // ---- exact inertia tensor of a uniform solid polyhedron (Robbins 1976) -
  // Polyhedron = union of tetrahedra (origin, face-triangle). Each contributes
  // V/30 * (sum of products of vertex coords) to the inertia components.
  function solidInertia(vertices, faces, mass) {
    // outward-wound face triangles as world vertex coords
    let vol = 0;
    let Ixx=0, Iyy=0, Izz=0, Ixy=0, Ixz=0, Iyz=0;
    const K = 1/30;
    for (const f of faces) {
      const a = vertices[f[0]], b = vertices[f[1]], c = vertices[f[2]];
      const V = vDot(a, vCross(b, c)) / 6; // signed tetra volume (origin at center)
      vol += V;
      const k = K * V;
