  }

  // ---- convex-polyhedron face extraction --------------------------------
  // Returns { faces: index-triples, edges, adj } for a convex polyhedron.
  function extractFaces(vertices) {
    const n = vertices.length;
    let edge = Infinity;
    for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
      const d = vLen(vSub(vertices[i], vertices[j]));
      if (d < edge) edge = d;
    }
    const adj = Array.from({length: n}, () => []);
    const EPS = edge * 1e-6;
    for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
      if (Math.abs(vLen(vSub(vertices[i], vertices[j])) - edge) < EPS) { adj[i].push(j); adj[j].push(i); }
    }
    // face test: (i,j,k) is a face iff i-j and j-k are edges and the three are
    // coplanar & form an outward triangle. For a convex polyhedron, each edge
    // bounds exactly two faces. We enumerate, per vertex, the 5 neighbors in
    // angular order about the radial direction; consecutive pairs are faces.
    const faceSet = new Set();
    const key = (a,b,c) => [a,b,c].sort((x,y)=>x-y).join(',');
    for (let i = 0; i < n; i++) {
      const ri = vNorm(vertices[i]);
      let ref = [1,0,0];
      if (Math.abs(vDot(ri, ref)) > 0.9) ref = [0,1,0];
      const u = vNorm(vSub(ref, vScale(ri, vDot(ri, ref)))); // ref minus radial comp
      const w = vNorm(vCross(ri, u));
      const order = adj[i].map(nn => {
        const d = vNorm(vSub(vertices[nn], vertices[i]));
        return [nn, Math.atan2(vDot(d, w), vDot(d, u))];
      }).sort((p, q) => p[1] - q[1]);
      for (let k = 0; k < order.length; k++) {
        const a = order[k][0], b = order[(k + 1) % order.length][0];
        faceSet.add(key(i, a, b));
      }
    }
    const faces = Array.from(faceSet).map(s => s.split(',').map(Number));
    // consistent winding: outward normal (a x b) dot (centroid) > 0
    for (let f = 0; f < faces.length; f++) {
      const [a, b, c] = faces[f];
      const A = vertices[a], B = vertices[b], C = vertices[c];
      const nm = vCross(vSub(B, A), vSub(C, A));
      const cent = vScale(vAdd(vAdd(A, B), C), 1/3);
      if (vDot(nm, cent) < 0) faces[f] = [c, b, a]; // flip to outward
    }
    return { faces, adj };
  }

  // ---- exact inertia tensor of a uniform solid polyhedron (Robbins 1976) -
  // Polyhedron = union of tetrahedra (origin, face-triangle). Each contributes
  // V/30 * (sum of products of vertex coords) to the inertia components.
  function solidInertia(vertices, faces, mass) {
    // outward-wound face triangles as world vertex coords
    let vol = 0;
    let Ixx=0, Iyy=0, Izz=0, Ixy=0, Ixz=0, Iyz=0;
    const K = 1/30;
    for (const f of faces) {
      const a = vertices[f[0]], b = vertices[f[1]], c = vertices[f[2]];
      const V = vDot(a, vCross(b, c)) / 6; // signed tetra volume (origin at center)
      vol += V;
      const k = K * V;
      Ixx += k*(a[0]*a[0] + b[0]*b[0] + c[0]*c[0]);
      Iyy += k*(a[1]*a[1] + b[1]*b[1] + c[1]*c[1]);
      Izz += k*(a[2]*a[2] + b[2]*b[2] + c[2]*c[2]);
      Ixy += k*(a[0]*a[1] + b[0]*b[1] + c[0]*c[1]);
      Ixz += k*(a[0]*a[2] + b[0]*b[2] + c[0]*c[2]);
      Iyz += k*(a[1]*a[2] + b[1]*b[2] + c[1]*c[2]);
    }
    const dens = mass / vol; // vol > 0 for outward faces
    return [
      [ Ixx*dens, Ixy*dens, Ixz*dens ],
      [ Ixy*dens, Iyy*dens, Iyz*dens ],
      [ Ixz*dens, Iyz*dens, Izz*dens ]
    ];
  }
  function invSym3(T) {
    const a=T[0][0], b=T[0][1], c=T[0][2];
    const d=T[1][0], e=T[1][1], f=T[1][2];
    const g=T[2][0], h=T[2][1], i=T[2][2];
    const det = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g);
    const inv = 1/det;
    return [
      [ (e*i - f*h)*inv, (c*h - b*i)*inv, (b*f - c*e)*inv ],
      [ (f*g - d*i)*inv, (a*i - c*g)*inv, (c*d - a*f)*inv ],
      [ (d*h - e*g)*inv, (b*g - a*h)*inv, (a*e - b*d)*inv ]
    ];
  }
  function mat3Vec(M, v) {
    return [
      M[0][0]*v[0] + M[0][1]*v[1] + M[0][2]*v[2],
      M[1][0]*v[0] + M[1][1]*v[1] + M[1][2]*v[2],
      M[2][0]*v[0] + M[2][1]*v[1] + M[2][2]*v[2]
    ];
  }

  // ---- build the d20 geometry ------------------------------------------
  function buildD20() {
    const phi = (1 + Math.sqrt(5)) / 2;
    const base = [
      [ 0,  1,  phi], [ 0,  1, -phi], [ 0, -1,  phi], [ 0, -1, -phi],
      [ 1,  phi, 0], [ 1, -phi, 0], [-1,  phi, 0], [-1, -phi, 0],
      [ phi, 0,  1], [ phi, 0, -1], [-phi, 0,  1], [-phi, 0, -1]
    ];
    const scale = R_CIRC / Math.sqrt(1 + phi * phi);
    const vertices = base.map(v => [v[0]*scale, v[1]*scale, v[2]*scale]);
    const { faces } = extractFaces(vertices);
    const normals = faces.map(f => vNorm(vCross(vSub(vertices[f[1]], vertices[f[0]]),
                                                vSub(vertices[f[2]], vertices[f[0]]))));
    const faceCenters = faces.map(f => vScale(vAdd(vAdd(vertices[f[0]], vertices[f[1]]),
                                                    vertices[f[2]]), 1/3));
    // opposite faces: normals ~ antiparallel
    const opp = new Array(20).fill(-1);
    for (let i = 0; i < 20; i++) for (let j = i+1; j < 20; j++) {
      if (vDot(normals[i], normals[j]) < -0.9999) { opp[i] = j; opp[j] = i; }
    }
    // number 1..20, opposite pairs sum to 21, deterministic by index order
    const numbers = new Array(20).fill(0);
    const assigned = new Array(20).fill(false);
    let n = 1;
    for (let i = 0; i < 20 && n <= 10; i++) {
      if (assigned[i]) continue;
      const j = opp[i];
      numbers[i] = n; numbers[j] = 21 - n;
      assigned[i] = assigned[j] = true;
      n++;
    }
    const inertia = solidInertia(vertices, faces, MASS);
    return {
      vertices, faces, normals, faceCenters, opp, numbers,
      Rc: R_CIRC, mass: MASS, inertia, invInertia: invSym3(inertia)
    };
  }

  // ---- die factory -----------------------------------------------------
  function createD20() {
    const geo = buildD20();
    return {
      geo,
      pos: v3(0, R_CIRC + 0.005, 0),
      quat: qIdentity(),
      vel: v3(0, 0, 0),
      angVel: v3(0, 0, 0),
      t: 0, steps: 0, settled: false, stillTimer: 0, result: 0
    };
  }

  // ---- world-space queries ---------------------------------------------
  const worldVertex = (die, i) => vAdd(die.pos, qRotate(die.quat, die.geo.vertices[i]));
  const faceNormalWorld = (die, f) => qRotate(die.quat, die.geo.normals[f]);
  const faceCenterWorld = (die, f) => vAdd(die.pos, qRotate(die.quat, die.geo.faceCenters[f]));

  // ---- impulse ---------------------------------------------------------
  function applyImpulse(die, p, J) {
    const r = vSub(p, die.pos);
    die.vel = vAdd(die.vel, vScale(J, 1/die.geo.mass));
    die.angVel = vAdd(die.angVel, mat3Vec(die.geo.invInertia, vCross(r, J)));
  }

  // A wrist fling reduced to one impulse. grabPoint is the world point the
  // hand was holding (e.g. from pickFace); v is the release velocity (m/s).
  // |v| is clamped to THROW_SPEED_MAX, then a single impulse J = m * v is
  // applied at grabPoint: linear momentum J, angular momentum r x J about
  // the CM. Pure and deterministic (no randomness); operates on die state.
