      const P = [ ray.origin[0] + ray.dir[0]*t, ray.origin[1] + ray.dir[1]*t, ray.origin[2] + ray.dir[2]*t ];
      const bc = barycentric(P, A, B, C);
      if (bc[0] < -1e-4 || bc[1] < -1e-4 || bc[2] < -1e-4) continue;
      const depth = dot(sub(P, cam.pos), basis().f);
      if (!best || depth < best.depth) best = { face: f, number: die.geo.numbers[f], bary: bc, world: P, center: D.faceCenterWorld(die, f), depth };
    }
    return best;
  }

  // ---- build the per-frame render model (DOM-free, testable) -----------
  // Single fixed directional light. Lambertian shade per face. Numbers on
  // every face. The settled face-up face gets a subtle brightness boost.
  const LIGHT = norm([0.32, 0.78, 0.44]);   // fixed key-light direction (toward the light)
  const BASE = [78, 86, 114];               // die base color (dark indigo-slate)
  const KEY  = [152, 160, 190];             // light added by the key
  const LANDING_BOOST = [42, 46, 58];       // subtle brighten on the face-up face
  const TABLE_TOP = [34, 36, 46];
  const TABLE_EDGE = [70, 74, 96];
  const BG = [20, 21, 27];

  function buildRenderModel(die) {
    const wv = new Array(12);
    for (let i = 0; i < 12; i++) wv[i] = project(D.worldVertex(die, i));
    const settledFace = die.settled ? faceIndexOfNumber(die) : -1;
    const faces = [];
    for (let f = 0; f < 20; f++) {
      const idx = die.geo.faces[f];
      const p0 = wv[idx[0]], p1 = wv[idx[1]], p2 = wv[idx[2]];
      const depth = (p0.depth + p1.depth + p2.depth) / 3;
      const n = D.faceNormalWorld(die, f);
      const facing = dot(n, sub(D.faceCenterWorld(die, f), cam.pos)) < 0; // normal toward camera
      if (!facing) continue;
      const nsh = Math.max(0, dot(n, LIGHT));
      let r = BASE[0] + KEY[0]*nsh, g = BASE[1] + KEY[1]*nsh, b = BASE[2] + KEY[2]*nsh;
      if (f === settledFace) { r += LANDING_BOOST[0]; g += LANDING_BOOST[1]; b += LANDING_BOOST[2]; }
      const cc = D.faceCenterWorld(die, f);
      const pc = project(cc);
      const lum = 0.299*r + 0.587*g + 0.114*b;
      faces.push({
        f, number: die.geo.numbers[f], depth, facing: true,
        pts: [ {x:p0.x, y:p0.y}, {x:p1.x, y:p1.y}, {x:p2.x, y:p2.y} ],
        color: [Math.round(clamp(r,0,255)), Math.round(clamp(g,0,255)), Math.round(clamp(b,0,255))],
        labelAt: { x: pc.x, y: pc.y },
        labelDark: lum > 150   // dark number on a bright face, light on a dark face
      });
    }
    // painter's algorithm: far -> near
    faces.sort((a, b) => b.depth - a.depth);
    // table quad (corners of the bounded rectangle at y=0)
    const corners = [
      project([-TABLE, 0, -TABLE]), project([TABLE, 0, -TABLE]),
      project([TABLE, 0,  TABLE]), project([-TABLE, 0,  TABLE])
    ];
    const tableDepth = (corners[0].depth + corners[2].depth) / 2;
    return { wv, faces, table: { pts: corners.map(c => ({x:c.x, y:c.y})), depth: tableDepth } };
  }
  function faceIndexOfNumber(die) {
    const target = D.faceUp(die);
    for (let f = 0; f < 20; f++) if (die.geo.numbers[f] === target) return f;
    return -1;
  }

  // ---- public (headless-testable) API for the next step ---------------
  global.DICE = {
    cam, project, unproject, rayTablePlane, pickFace, buildRenderModel,
    faceIndexOfNumber, TABLE,
    camInfo: () => ({ pos: cam.pos.slice(), target: cam.target.slice(), fov: cam.fov, W: cam.W, H: cam.H, light: LIGHT.slice() })
  };

  // ============================ BROWSER HALF ============================
  if (typeof window === 'undefined') return;

  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const numEl = document.getElementById('num');
  const statusEl = document.getElementById('status');
  const die = D.createD20();
  let shown = null;            // last number shown in the readout
  let lastSettled = false;

  function resize() {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = window.innerWidth, h = window.innerHeight;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
    canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);   // draw in css px
    cam.W = w; cam.H = h;
  }
  window.addEventListener('resize', resize);
  resize();

  function tri(c, pts, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y); ctx.lineTo(pts[1].x, pts[1].y); ctx.lineTo(pts[2].x, pts[2].y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
  }
  function quad(c, pts, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y); for (let i = 1; i < 4; i++) ctx.lineTo(pts[i].x, pts[i].y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 2; ctx.stroke(); }
  }
  const rgb = c => `rgb(${c[0]},${c[1]},${c[2]})`;

  function draw() {
    // backdrop
    ctx.fillStyle = rgb(BG); ctx.fillRect(0, 0, cam.W, cam.H);
    const m = buildRenderModel(die);
    // table (always behind the die in depth; drawn first)
    quad(ctx, m.table.pts, rgb(TABLE_TOP), rgb(TABLE_EDGE));
    // die faces, far -> near
    for (const f of m.faces) {
      tri(ctx, f.pts, rgb(f.color), rgb(f.color));
      // number
      const faceH = Math.max(
        Math.abs(f.pts[0].y - f.pts[1].y), Math.abs(f.pts[1].y - f.pts[2].y), Math.abs(f.pts[2].y - f.pts[0].y));
      const fs = clamp(0.5 * faceH, 8, 40);
      ctx.font = `800 ${fs.toFixed(1)}px system-ui, sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillStyle = f.labelDark ? 'rgb(24,28,44)' : 'rgb(240,242,250)';
      ctx.fillText(String(f.number), f.labelAt.x, f.labelAt.y);
    }
    // readout
    if (die.settled && lastSettled === false) lastSettled = true;
    if (die.settled && shown !== die.result) {
      shown = die.result;
      numEl.textContent = String(die.result);
      statusEl.textContent = 'settled';
    }
  }

  function rethrow() {
    const rng = D.prng((Math.floor(performance.now()) ^ 0x9E3779B9) >>> 0);
    die.pos = [ (rng()-0.5)*0.14, 0.14 + rng()*0.06, (rng()-0.5)*0.14 ];
    die.vel = [ (rng()-0.5)*3.0, -0.2 + rng()*0.5, (rng()-0.5)*3.0 ];
    die.angVel = [ (rng()-0.5)*55, (rng()-0.5)*55, (rng()-0.5)*55 ];
    die.quat = D.qNorm(D.qFromAxisAngle([rng()-0.5, rng()-0.5, rng()-0.5], rng()*Math.PI*2));
    for (let k = 0; k < 2; k++) die.quat = D.qNorm(D.qMul(D.qFromAxisAngle([rng()-0.5,rng()-0.5,rng()-0.5], rng()*Math.PI*2), die.quat));
    die.t = 0; die.steps = 0; die.settled = false; die.stillTimer = 0; die.result = 0;
    shown = null; lastSettled = false;
    numEl.textContent = '…'; statusEl.textContent = 'rolling';
  }

  const params = new URLSearchParams(window.location.search);
  const demo = params.get('demo') === '1';
  if (demo) document.getElementById('diego').textContent = 'demo (auto-throw)';
  if (demo) rethrow();
  let demoTimer = null;
  if (demo) demoTimer = setInterval(() => { if (die.settled) rethrow(); }, 2600);

  let last = performance.now();
  function frame(now) {
    let dt = (now - last) / 1000; last = now;
    if (dt > 0.1) dt = 0.1;               // clamp big gaps (tab was backgrounded)
    if (!die.settled) D.advance(die, dt);
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // keep a dev handle for the next step / console poking
  window.__dice = { die, rethrow, D, DICE: global.DICE };
})(typeof globalThis !== 'undefined' ? globalThis : this);
/* @renderer-end */
</script>

