    // determinism: identical initial state, twice
    const a = D.createD20(), b = D.createD20();
    a.pos = b.pos = [0.02, 0.12, -0.01];
    a.vel = b.vel = [0.6, -0.2, 0.35];
    a.angVel = b.angVel = [18, -9, 12];
    a.quat = b.quat = D.qFromAxisAngle([1,2,3], 0.7);
    D.advance(a, 40); D.advance(b, 40);
