  // ---- die factory -----------------------------------------------------
  function createD20() {
    const geo = buildD20();
    return {
      geo,
      pos: v3(0, R_CIRC + 0.005, 0),
      quat: qIdentity(),
      vel: v3(0, 0, 0),
      angVel: v3(0, 0, 0),
      t: 0, steps: 0, settled: false, stillTimer: 0, result: 0
