  function runSelfTest(nThrows) {
    nThrows = nThrows || 50;
    const rng = D.prng(12345);
    let settled = 0, within20 = 0, over20 = 0;
    const results = [], hist = {};

    // determinism: identical initial state, twice
    const a = D.createD20(), b = D.createD20();
    a.pos = b.pos = [0.02, 0.12, -0.01];
    a.vel = b.vel = [0.6, -0.2, 0.35];
    a.angVel = b.angVel = [18, -9, 12];
    a.quat = b.quat = D.qFromAxisAngle([1,2,3], 0.7);
    D.advance(a, 40); D.advance(b, 40);
    const detPass = a.result === b.result && a.settled && b.settled;

    for (let i = 0; i < nThrows; i++) {
      const die = D.createD20();
      throwState(die, rng);
      D.advance(die, 25);
      if (die.settled) settled++;
      if (die.t <= 20) within20++; else over20++;
      results.push(die.result);
      hist[die.result] = (hist[die.result] || 0) + 1;
    }

    const distinct = Object.keys(hist).length;
    const histStr = Object.keys(hist).sort((x,y)=>x-y).map(k => k+':'+hist[k]).join(' ');
