  const BASE = [78, 86, 114];               // die base color (dark indigo-slate)
  const KEY  = [152, 160, 190];             // light added by the key
  const LANDING_BOOST = [42, 46, 58];       // subtle brighten on the face-up face
  const TABLE_TOP = [34, 36, 46];
  const TABLE_EDGE = [70, 74, 96];
  const BG = [20, 21, 27];

  function buildRenderModel(die) {
    const wv = new Array(12);
    for (let i = 0; i < 12; i++) wv[i] = project(D.worldVertex(die, i));
    const settledFace = die.settled ? faceIndexOfNumber(die) : -1;
    const faces = [];
    for (let f = 0; f < 20; f++) {
      const idx = die.geo.faces[f];
      const p0 = wv[idx[0]], p1 = wv[idx[1]], p2 = wv[idx[2]];
      const depth = (p0.depth + p1.depth + p2.depth) / 3;
      const n = D.faceNormalWorld(die, f);
      const facing = dot(n, sub(D.faceCenterWorld(die, f), cam.pos)) < 0; // normal toward camera
      if (!facing) continue;
      const nsh = Math.max(0, dot(n, LIGHT));
      let r = BASE[0] + KEY[0]*nsh, g = BASE[1] + KEY[1]*nsh, b = BASE[2] + KEY[2]*nsh;
      if (f === settledFace) { r += LANDING_BOOST[0]; g += LANDING_BOOST[1]; b += LANDING_BOOST[2]; }
      const cc = D.faceCenterWorld(die, f);
      const pc = project(cc);
      const lum = 0.299*r + 0.587*g + 0.114*b;
      faces.push({
