// Dev harness: extract the pure physics core + self-test from index.html and
// run them headless in node. No DOM. Usage: node test.mjs
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, 'index.html'), 'utf8');

function block(id) {
  const start = html.indexOf(`<script id="${id}">`);
  const end = html.indexOf(`</script>`, start);
  if (start < 0 || end < 0) throw new Error('missing <script id="' + id + '">');
  return html.slice(start + `<script id="${id}">`.length, end);
}

// Evaluate both pure blocks in this global scope, in order.
const core = block('physics-core');
const selftest = block('selftest');
(0, eval)(core);
(0, eval)(selftest);

const r = globalThis.__d20SelfTest(50);
// compact machine summary
console.log('SUMMARY settled=' + r.settled + '/' + r.throws +
  ' within20=' + r.within20 + ' det=' + (r.detPass ? 'PASS' : 'FAIL') +
  ' distinct=' + r.distinct);

