(function (global) {
  'use strict';
  const D = global.D20;

  function throwState(die, rng) {
    die.pos = [ (rng()-0.5)*0.12, 0.05 + rng()*0.07, (rng()-0.5)*0.12 ];
    die.vel = [ (rng()-0.5)*2.5, -0.4 + rng()*0.6, (rng()-0.5)*2.5 ];
    die.angVel = [ (rng()-0.5)*45, (rng()-0.5)*45, (rng()-0.5)*45 ];
    die.quat = [0,0,0,1];
    for (let k = 0; k < 3; k++) {
      const axis = [rng()-0.5, rng()-0.5, rng()-0.5];
      const ang = rng()*Math.PI*2;
      die.quat = D.qMul(D.qFromAxisAngle(axis, ang), die.quat);
    }
    die.quat = D.qNorm(die.quat);
  }

  function runSelfTest(nThrows) {
    nThrows = nThrows || 50;
    const rng = D.prng(12345);
    let settled = 0, within20 = 0, over20 = 0;
    const results = [], hist = {};

    // determinism: identical initial state, twice
    const a = D.createD20(), b = D.createD20();
    a.pos = b.pos = [0.02, 0.12, -0.01];
    a.vel = b.vel = [0.6, -0.2, 0.35];
    a.angVel = b.angVel = [18, -9, 12];
    a.quat = b.quat = D.qFromAxisAngle([1,2,3], 0.7);
    D.advance(a, 40); D.advance(b, 40);
    const detPass = a.result === b.result && a.settled && b.settled;

    for (let i = 0; i < nThrows; i++) {
      const die = D.createD20();
      throwState(die, rng);
      D.advance(die, 25);
      if (die.settled) settled++;
      if (die.t <= 20) within20++; else over20++;
      results.push(die.result);
      hist[die.result] = (hist[die.result] || 0) + 1;
    }

    const distinct = Object.keys(hist).length;
    const histStr = Object.keys(hist).sort((x,y)=>x-y).map(k => k+':'+hist[k]).join(' ');
    console.log('=== d20 physics self-test ===');
    console.log('throws=' + nThrows + ' settled=' + settled + '/' + nThrows +
      ' within20s=' + within20 + ' over20s=' + over20);
    console.log('determinism=' + (detPass ? 'PASS' : 'FAIL') +
      ' (faces ' + a.result + ' == ' + b.result + ')');
    console.log('distinct faces=' + distinct + '  hist=' + histStr);
    console.log('samples=' + results.slice(0, 20).join(','));
    return { throws: nThrows, settled, within20, over20, detPass,
             detFaces: [a.result, b.result], distinct, hist, samples: results };
  }

